import (
	"fmt"
)

resp, err := client.ProductListingSettings().GetProductListing(ctx, nil, nil)
if err != nil {
	log.Fatal(err)
}
settings := resp.Map().(map[string]any)["product_listing"].(map[string]any)
load := settings["load"].(map[string]any)
sorting := settings["sorting"].(map[string]any)
fmt.Println(load["type"], load["pagination"].(map[string]any)["per_page"], sorting["enabled"], sorting["sort_by"])

